  border-radius: 9px;
  background: var(--mk-surface, #fbf9f4);
  box-shadow: inset 1px 1px 0 rgb(255 255 255 / 0.5), 2px 3px 0 -1px rgb(var(--shade) / 0.1), 6px 14px 30px -16px rgb(var(--shade) / 0.5);
}

