/* ── Keycaps (press-depth-button, adapted): a face on a side band, a tight contact shadow under the band and a
   wide soft shadow under that. Hover lifts the face and widens the soft shadow; pressing drives the face down
   and collapses it; letting go springs back on a linear() curve sampled from the `pop` spring token. ────── */
.key {
  --d: 5px;
  --face: var(--mk-surface, #fbf9f4);
  --side: color-mix(in oklab, var(--mk-surface-2, #e9e5da) 62%, #6b5034);
  --text: var(--mk-ink, #11110f);
  --edge: var(--mk-line, #11110f24);
  --lip: rgb(255 255 255 / 0.75);
  position: relative;
  isolation: isolate;
  display: grid;
  flex: none;
  min-width: 2.75rem;
  margin: 0;
  padding: 0 0 var(--d);
  border: 0;
  border-radius: 11px;
  background: none;
  color: var(--text);
  font: inherit;
  font-size: 13.5px;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
.key[data-size='s'] { --d: 4px; border-radius: 9px; font-size: 13px; }
.key[data-size='l'] { --d: 7px; border-radius: 999px; font-size: 16px; }
.key[data-tone='ink'] {
  --face: var(--mk-ink, #11110f);
  --side: color-mix(in oklab, var(--mk-ink, #11110f) 72%, #8a6540);
  --text: var(--mk-bg, #f3f0e8);
  --edge: transparent;
  --lip: rgb(255 255 255 / 0.2);
}
.key[data-tone='signal'] {
  --face: var(--mk-signal, #bf2f09);
  --side: color-mix(in oklab, var(--mk-signal, #bf2f09) 58%, #000);
  --text: var(--mk-on-signal, #ffffff);
  --edge: transparent;
  --lip: rgb(255 255 255 / 0.3);
}
:global([data-theme='dark']) .key[data-tone='paper'] {
  --face: var(--mk-surface-2, #22221e);
  --side: color-mix(in oklab, var(--mk-surface-2, #22221e) 55%, #000);
  --lip: rgb(255 255 255 / 0.1);
}

.keyShadow {
  position: absolute;
  z-index: -1;
  inset: auto 3% calc(var(--d) * -0.45) 8%;
  height: 72%;
  border-radius: 42%;
  background: rgb(var(--shade) / 0.3);
  filter: blur(7px);
  transform: translate(3px, 3px);
  transition:
    transform var(--release-dur, 600ms) var(--release-ease, ease),
    opacity var(--release-dur, 600ms) var(--release-ease, ease);
}
:global([data-theme='dark']) .keyShadow { background: rgb(0 0 0 / 0.55); }
.keySide {
  position: absolute;
  inset: var(--d) 0 0;
  border-radius: inherit;
  background: var(--side);
  box-shadow: inset 0 0 0 1px var(--edge), 1px 1.5px 1px rgb(var(--shade) / 0.3);
}
.keyFace {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 2.625rem;
  padding: 0 1rem;
  border-radius: inherit;
  /* lit from the upper left: a slightly brighter top-left corner and a 1px lip on the lit edges */
  background: linear-gradient(155deg, color-mix(in oklab, var(--face) 90%, #fff) 0%, var(--face) 55%);
  box-shadow: inset 0 0 0 1px var(--edge), inset 1px 1px 0 var(--lip);
  font-weight: 550;
  white-space: nowrap;
  transform: translateY(0);
  transition: transform var(--release-dur, 600ms) var(--release-ease, ease);
}
.key[data-size='s'] .keyFace { min-height: 2.125rem; padding: 0 0.75rem; }
.key[data-size='l'] .keyFace { min-height: 3.75rem; padding: 0 1.9rem; }

@media (hover: hover) {
  .key:hover:not(:disabled):not(:has(input:disabled)) .keyFace { transform: translateY(-1.5px); }
  .key:hover:not(:disabled):not(:has(input:disabled)) .keyShadow { transform: translate(5px, 6px) scale(1.05); opacity: 0.8; }
}
.key:active:not(:disabled):not(:has(input:disabled)) .keyFace {
  transform: translateY(calc(var(--d) * 0.82));
  transition: transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease);
}
.key:active:not(:disabled):not(:has(input:disabled)) .keyShadow {
  transform: translate(1px, 1px) scale(0.92, 0.45);
  opacity: 0.5;
  transition:
    transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease),
    opacity var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease);
}

/* Latching keys (radio choices): the chosen one stays pressed in, with an ink face. */
.key[data-latch]:has(input:checked) {
  --face: var(--mk-ink, #11110f);
  --side: color-mix(in oklab, var(--mk-ink, #11110f) 72%, #8a6540);
  --text: var(--mk-bg, #f3f0e8);
  --edge: transparent;
  --lip: rgb(255 255 255 / 0.16);
}
.key[data-latch]:has(input:checked) .keyFace { transform: translateY(calc(var(--d) * 0.55)); }
.key[data-latch]:has(input:checked) .keyShadow { transform: translate(1.5px, 2px) scale(0.95, 0.65); opacity: 0.7; }
.key[data-latch]:has(input:checked) .glyph { filter: drop-shadow(0 0 0.5px rgb(255 255 255 / 0.5)); }

.key:focus-visible, .key:has(input:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 3px; }

/* Disabled: sunk flush with the base, flat and quiet; it rises when it unlocks. */
.key:disabled, .key:has(input:disabled) {
  cursor: not-allowed;
  --face: color-mix(in oklab, var(--mk-surface-2, #e9e5da) 65%, var(--mk-surface, #fbf9f4));
  --text: var(--mk-ink-muted, #5c5a52);
  --edge: var(--mk-line, #11110f24);
  --lip: transparent;
}
.key:disabled .keyFace, .key:has(input:disabled) .keyFace { transform: translateY(calc(var(--d) * 0.9)); }
.key:disabled .keyShadow, .key:has(input:disabled) .keyShadow { opacity: 0; }
.key:has(input:disabled) .glyph { opacity: 0.55; }
.glyph { display: block; }

/* Reduced motion: every state is applied at once, no spring and no shadow travel. */
.root[data-reduced] .keyFace, .root[data-reduced] .keyShadow { transition: none; }
@media (prefers-reduced-motion: reduce) { .keyFace, .keyShadow { transition: none; } }

